let secrets;
try {
    secrets = JSON.parse(msg.payload);
} catch (e) {
    node.error('Could not parse secrets file: ' + e.message, msg);
    return null;
}
msg.secrets = secrets;
msg.job_started_at = new Date().toISOString();
const nowNs = Date.now() * 1000000;
msg.url = secrets.influxdb_url + '/api/v2/write?org=' + secrets.influxdb_org + '&bucket=' + secrets.influxdb_bucket + '&precision=ns';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + secrets.influxdb_token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = 'sync_job_runs,job_name=medications_influx_cleanup,status=started value=1 ' + nowNs;
return msg;

const secrets = msg.secrets;
msg.url = secrets.influxdb_url + '/api/v2/delete?org=' + encodeURIComponent(secrets.influxdb_org) + '&bucket=' + encodeURIComponent(secrets.influxdb_bucket);
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + secrets.influxdb_token, 'Content-Type': 'application/json' };
msg.payload = JSON.stringify({
    start: '1970-01-01T00:00:00Z',
    stop: new Date().toISOString(),
    predicate: '_measurement="medications"'
});
return msg;

// InfluxDB v2's delete API returns 204 No Content on success, with no
// body. Node-RED's http request node puts the HTTP status on
// msg.statusCode regardless of ret type.
if (msg.statusCode !== 204) {
    msg.job_failed = true;
    msg.failure_code = 'influxdb_delete_failed';
    msg.failure_detail = 'expected 204, got ' + msg.statusCode + ': ' + (msg.payload || '').toString().slice(0, 300);
    return [null, msg];
}
node.warn('InfluxDB: medications measurement deleted (204). Re-pulling from GoDaddy to repopulate with corrected timestamps...');
msg.target = 'GoDaddy Pull (Full Sync entry)';
return [msg, null];

const nowNs = Date.now() * 1000000;
const durationMs = Date.now() - new Date(msg.job_started_at).getTime();
msg.influx_finish_point = 'sync_job_runs,job_name=medications_influx_cleanup,status=success duration_ms=' + durationMs + ' ' + nowNs;
msg.sqlite_job = { job_name: 'medications_influx_cleanup', mode: 'success', last_success: new Date().toISOString(), last_attempt: new Date().toISOString(), last_attempt_ok: 1 };
node.warn('Medications InfluxDB cleanup complete — old duplicate points deleted, fresh midnight-UTC points repopulated from GoDaddy. Safe to disable/delete this tab now.');
return msg;

const nowNs = Date.now() * 1000000;
const code = msg.failure_code || 'unknown_error';
const detail = (msg.failure_detail || '').replace(/([ ,="])/g, '\\$1');
msg.influx_finish_point = 'sync_job_runs,job_name=medications_influx_cleanup,status=failed,failure_code=' + code + ' detail="' + detail + '" ' + nowNs;
msg.sqlite_job = { job_name: 'medications_influx_cleanup', mode: 'failure', last_attempt: new Date().toISOString(), last_attempt_ok: 0, last_error: code + ': ' + (msg.failure_detail || '') };
node.warn('Medications InfluxDB cleanup FAILED: ' + code + ' - ' + msg.failure_detail);
return msg;

msg.url = msg.secrets.influxdb_url + '/api/v2/write?org=' + msg.secrets.influxdb_org + '&bucket=' + msg.secrets.influxdb_bucket + '&precision=ns';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + msg.secrets.influxdb_token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = msg.influx_finish_point;
return msg;

msg.topic = "CREATE TABLE IF NOT EXISTS job_status (" +
    "job_name TEXT PRIMARY KEY, last_success TEXT, last_attempt TEXT, " +
    "last_attempt_ok INTEGER, last_error TEXT, checkpoint TEXT, updated_at TEXT)";
return msg;

function esc(s) { return "'" + String(s).replace(/'/g, "''") + "'"; }
function sqlVal(v) { return (v === null || v === undefined) ? 'NULL' : (typeof v === 'number' ? v : esc(v)); }
const j = msg.sqlite_job;
const now = new Date().toISOString();
const cols = ['job_name', 'last_success', 'last_attempt', 'last_attempt_ok', 'last_error', 'checkpoint', 'updated_at'];
const vals = [j.job_name, j.last_success ?? null, j.last_attempt, j.last_attempt_ok, j.last_error ?? null, j.checkpoint ?? null, now];
const setClauses = ['last_attempt=excluded.last_attempt', 'last_attempt_ok=excluded.last_attempt_ok', 'updated_at=excluded.updated_at'];
if (j.mode === 'success') {
    setClauses.push('last_success=excluded.last_success', 'last_error=NULL');
} else {
    setClauses.push('last_error=excluded.last_error');
}
msg.topic = 'INSERT INTO job_status (' + cols.join(', ') + ') VALUES (' + vals.map(sqlVal).join(', ') + ') ' +
    'ON CONFLICT(job_name) DO UPDATE SET ' + setClauses.join(', ');
return msg;
